Here's an example implementation of a C++ function that takes a reference to a std::string containing Markdown formatted text and returns a std::string containing HTML formatted text:

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <regex>

// Map Markdown syntax to HTML tags
const std::unordered_map<std::string, std::string> markdown_to_html = {
    {"# ", "<h1>"},
    {"## ", "<h2>"},
    {"### ", "<h3>"},
    {"#### ", "<h4>"},
    {"##### ", "<h5>"},
    {"###### ", "<h6>"},
    {"* ", "<em>"},
    {"** ", "<strong>"},
    {"~~ ", "<del>"},
    {"` ", "<code>"},
    {"[ ](", "<a href=\"\">"},
    {"](", ")</a>"},
    {"< ", "&lt;"},
    {"> ", "&gt;"},
    {"\\ ", "&#92;"},
    { "\n", "<br>" }
};

std::string convertMarkdownToHTML(std::string& markdown) {
    std::string html;

    // Replace each Markdown syntax with its corresponding HTML tag
    for (size_t I = 0; I < markdown.length(); ++i) {
        std::string match;

        // Check if the current character is the start of a Markdown syntax
        for (const auto& [md, html_tag] : markdown_to_html) {
            if (markdown.find(md, i) == i) {
                match = md;
                break;
            }
        }

        // If a Markdown syntax was found, replace it with its HTML tag
        if (!match.empty()) {
            size_t end_pos = markdown.find_first_not_of(" \t\n\r\f\v", i + match.length());
            std::string content = markdown.substr(i + match.length(), end_pos - I - match.length());
            html += markdown_to_html[match] + content + " ";
            i = end_pos - 1;
        } else {
            html += markdown[i];
        }
    }

    return html;
}

int main() {
    std::string markdown = "## Hello, *world*!\nThis is a **test** of the #conversion system. [Google](https://www.google.com/) is a popular search engine.";

    std::string html = convertMarkdownToHTML(markdown);

    std::cout << "Markdown:\n" << markdown << "\n\n";
    std::cout << "HTML:\n" << html << "\n";

    return 0;
}
```

This implementation uses a constant `unordered_map` to map Markdown syntax to their corresponding HTML tags. The function iterates through the input Markdown string and replaces each Markdown syntax with its corresponding HTML tag.

Note that this implementation only covers a basic set of Markdown syntax. A more robust solution would require a more comprehensive Markdown parser and HTML generator, and may also require additional libraries or external tools.

